tool_calls:
awk -F: '
{
    target = $1;
    gsub(/^[ \t]+|[ \t]+$/, "", target);
    n = split($2, deps, /[ \t]+/);
    has_deps = 0;
    for (i = 1; i <= n; i++) {
        if (deps[i] != "") {
            print deps[i], target;
            has_deps = 1;
        }
    }
    if (!has_deps) {
        print target, target;
    }
}
' /project/deps.txt | tsort

cat << 'EOF' > /project/build.sh
#!/bin/bash
set -e

mkdir -p /project/out

# Topological sort of dependencies from /project/deps.txt
# tsort takes pairs "dep target" meaning dep comes before target
targets=$(awk -F: '
{
    target = $1;
    gsub(/^[ \t]+|[ \t]+$/, "", target);
    n = split($2, deps, /[ \t]+/);
    has_deps = 0;
    for (i = 1; i <= n; i++) {
        if (deps[i] != "") {
            print deps[i], target;
            has_deps = 1;
        }
    }
    if (!has_deps && target != "") {
        print target, target;
    }
}
' /project/deps.txt | tsort)

for t in $targets; do
    echo "built: $t" > "/project/out/$t"
    echo "$t"
done
EOF
chmod +x /project/build.sh

